create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,phone text,points integer not null default 0,created_at timestamptz default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,status text not null default 'pending',total_amount numeric(12,2) not null default 0,created_at timestamptz default now());
create table if not exists public.order_items(id bigint generated by default as identity primary key,order_id uuid not null references public.orders(id) on delete cascade,product_id text not null,product_name text not null,quantity integer not null check(quantity>0),unit_price numeric(12,2) not null default 0);
create table if not exists public.reviews(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,rating integer not null check(rating between 1 and 5),content text not null check(char_length(content) between 1 and 2000),image_url text,created_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,phone) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','Thành viên FrogNutri'),new.raw_user_meta_data->>'phone') on conflict(id) do update set full_name=excluded.full_name,phone=excluded.phone; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

alter table public.profiles enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.reviews enable row level security;
grant select,insert,update,delete on public.profiles,public.orders,public.order_items,public.reviews to authenticated;grant select on public.reviews to anon;
create policy profiles_select on public.profiles for select to authenticated using((select auth.uid())=id);create policy profiles_insert on public.profiles for insert to authenticated with check((select auth.uid())=id);create policy profiles_update on public.profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
create policy orders_select on public.orders for select to authenticated using((select auth.uid())=user_id);create policy orders_insert on public.orders for insert to authenticated with check((select auth.uid())=user_id);
create policy items_select on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=(select auth.uid())));create policy items_insert on public.order_items for insert to authenticated with check(exists(select 1 from public.orders o where o.id=order_id and o.user_id=(select auth.uid())));
create policy reviews_select on public.reviews for select to anon,authenticated using(true);create policy reviews_insert on public.reviews for insert to authenticated with check((select auth.uid())=user_id);create policy reviews_update on public.reviews for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);create policy reviews_delete on public.reviews for delete to authenticated using((select auth.uid())=user_id);
insert into storage.buckets(id,name,public) values('review-images','review-images',true) on conflict(id) do update set public=true;
create policy review_images_read on storage.objects for select to public using(bucket_id='review-images');create policy review_images_insert on storage.objects for insert to authenticated with check(bucket_id='review-images' and (storage.foldername(name))[1]=(select auth.uid())::text);create policy review_images_delete on storage.objects for delete to authenticated using(bucket_id='review-images' and owner_id=(select auth.uid())::text);
